<script setup>import{computed,onMounted,ref}from'vue';import{AlertTriangle,Building2,Download,RefreshCw,ShieldCheck}from'@lucide/vue';import{getCourseGovernanceCatalog}from'../api/courseGovernance';import{acquireOrgResource,getOrgMarketCatalog,getOrgMarketOrganizations,publishOrgResource,withdrawOrgResource}from'../api/organizationMarketplace';const orgs=ref([]),org=ref(''),data=ref(null),courses=ref([]),busy=ref(''),error=ref(''),notice=ref(''),q=ref('');const form=ref({course_id:'',title:'企业内训资源',summary:'组织内部可追溯的岗位技能学习资源',category:'转岗培训',tags:'AI,岗位技能'});const current=computed(()=>orgs.value.find(x=>x.id===org.value));const canManage=computed(()=>['manager','admin','platform_admin'].includes(current.value?.role));const copyAllowed=computed(()=>data.value?.policy?.copy_enabled&&data.value.policy.allowed_copy_roles.includes(current.value?.role==='platform_admin'?'admin':current.value?.role));const msg=e=>e?.detail?.message||e?.detail||e?.message||'操作失败';async function load(){busy.value='load';error.value='';try{orgs.value=(await getOrgMarketOrganizations()).items;if(!org.value)org.value=orgs.value[0]?.id||'';if(org.value)data.value=await getOrgMarketCatalog(org.value,q.value);try{courses.value=(await getCourseGovernanceCatalog()).courses||[]}catch{courses.value=[]}if(!form.value.course_id)form.value.course_id=courses.value[0]?.id||''}catch(e){error.value=msg(e)}finally{busy.value=''}}async function choose(){data.value=await getOrgMarketCatalog(org.value,q.value)}async function publish(){busy.value='publish';try{await publishOrgResource({organization_id:org.value,...form.value,tags:form.value.tags.split(',').map(x=>x.trim()).filter(Boolean)});notice.value='组织资源已按当前策略冻结发布';await load()}catch(e){error.value=msg(e);busy.value=''}}async function acquire(x){busy.value='acquire';try{const a=await acquireOrgResource(x.id);notice.value=`组织副本已创建：${a.derived_course_id}`}catch(e){error.value=msg(e)}finally{busy.value=''}}async function withdraw(x){busy.value='withdraw';try{await withdrawOrgResource(x.id,{reason:'组织管理者停止后续获取并保留成员历史副本',expected_version:x.lock_version});notice.value='资源已撤回，历史副本保持可用';await load()}catch(e){error.value=msg(e);busy.value=''}}onMounted(load)</script>
<template><main class="org-market"><header><div><p>PRIVATE ENTERPRISE MARKETPLACE</p><h2>组织私有学习市场</h2><span>租户隔离、策略控制复制、撤回保留成员历史</span></div><button aria-label="刷新组织市场" @click="load"><RefreshCw :size="16"/></button></header><div class="truth"><ShieldCheck :size="17"/><div><strong>{{data?.truth_label||'组织私有学习市场 · 冻结合成企业边界'}}</strong><span>{{data?.disclaimer}}</span></div></div><p v-if="error" class="error"><AlertTriangle :size="15"/>{{error}}</p><p v-if="notice" class="notice">{{notice}}</p><section class="scope"><Building2 :size="17"/><select v-model="org" aria-label="组织范围" @change="choose"><option v-for="x in orgs" :key="x.id" :value="x.id">{{x.name}} · {{x.role}}</option></select><div><strong>复制策略 {{data?.policy?.copy_enabled?'开启':'关闭'}}</strong><span>允许角色：{{data?.policy?.allowed_copy_roles?.join('、')||'无'}}</span></div><input v-model="q" aria-label="组织资源搜索" placeholder="搜索组织资源"/><button @click="choose">搜索</button></section><section v-if="canManage&&courses.length" class="publish"><div><h3>发布组织资源</h3><span>冻结内容、许可证和当前 sharing_policy。</span></div><select v-model="form.course_id" aria-label="组织市场课程"><option v-for="x in courses" :key="x.id" :value="x.id">{{x.title}} · {{x.version}}</option></select><input v-model="form.title" aria-label="组织资源标题"/><input v-model="form.summary" aria-label="组织资源摘要"/><input v-model="form.category" aria-label="组织资源分类"/><input v-model="form.tags" aria-label="组织资源标签"/><button @click="publish">发布</button></section><section class="catalog"><h3>组织资源目录</h3><div class="grid"><article v-for="x in data?.items||[]" :key="x.id" data-testid="org-resource"><div><strong>{{x.title}}</strong><em>{{x.status}}</em></div><p>{{x.summary}}</p><span>{{x.category}} · {{x.tags.join(' · ')}}</span><div class="license"><b>{{x.license.course_license||'未提供许可证'}}</b><small>{{x.license.course_origin}}</small></div><small>策略快照：{{x.policy.copy_enabled?'允许复制':'禁止复制'}} / {{x.policy.allowed_copy_roles.join('、')}}</small><footer><button :disabled="!copyAllowed||x.status!=='active'" title="获取组织副本" @click="acquire(x)"><Download :size="14"/>获取副本</button><button v-if="canManage&&x.status==='active'" @click="withdraw(x)">撤回</button></footer></article><p v-if="!data?.items?.length" class="empty">当前组织暂无资源</p></div></section></main></template>
<style scoped>.org-market{max-width:1180px;margin:0 auto;color:#26352d}header,.truth,.scope,footer{display:flex;align-items:center}header{justify-content:space-between}header p{margin:0;color:#738178;font-size:10px;font-weight:800;letter-spacing:.12em}h2{margin:4px 0;font-size:24px}header span,.truth span,.scope span,.publish span{display:block;color:#738078;font-size:10px}header button{display:grid;width:36px;height:36px;place-items:center;border:1px solid #dce6df;border-radius:7px;background:#fff}.truth{gap:8px;margin:14px 0;padding:11px;border-left:3px solid #3c765e;background:#edf6f0}.scope{display:grid;grid-template-columns:auto 1fr 1fr 1fr auto;gap:8px;padding:11px;background:#eef2ef}.scope select,.scope input,.publish select,.publish input{min-width:0;padding:9px;border:1px solid #d9e3dc;border-radius:6px;background:#fff}.scope button,.publish button,footer button{display:flex;align-items:center;justify-content:center;gap:5px;padding:9px;border:0;border-radius:6px;background:#304c3d;color:#fff}.publish{display:grid;grid-template-columns:1.1fr 1fr 1fr 1.4fr .8fr 1fr auto;gap:7px;align-items:end;margin:10px 0;padding:12px;border:1px solid #dde7df;background:#fff}.publish h3{margin:0;font-size:12px}.catalog{padding:12px;border:1px solid #dde7df;background:#fff}.catalog>h3{margin:0 0 9px;font-size:12px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.grid article{min-width:0;padding:12px;border:1px solid #e0e8e2}.grid article>div:first-child{display:flex;justify-content:space-between}.grid strong{font-size:12px}.grid em{font-size:9px;font-style:normal}.grid p,.grid span,.grid small{display:block;font-size:9px;line-height:1.5}.license{margin:8px 0;padding:8px;border-left:3px solid #c8a45c;background:#fff8ec}.license b,.license small{display:block;overflow-wrap:anywhere;font-size:9px}footer{gap:6px;margin-top:9px}footer button:disabled{opacity:.4}.error,.notice{padding:8px;font-size:10px}.error{display:flex;gap:5px;background:#fff0ed;color:#974c41}.notice{background:#edf5ef}.empty{grid-column:1/-1}@media(max-width:900px){.publish{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.scope,.publish,.grid{grid-template-columns:1fr}.scope>svg{display:none}footer{align-items:stretch;flex-direction:column}}</style>
